16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.util.*;
25	
26	/**
27	 * Simple JavaBean domain object representing an owner.
28	 *
29	 * @author Ken Krebs
30	 * @author Juergen Hoeller
31	 * @author Sam Brannen
32	 * @author Michael Isvy
33	 */
34	@Entity
35	@Table(name = "owners")
36	public class Owner extends Person {
37	    @Column(name = "address")
38	    @NotEmpty
39	    private String address;
40	
41	    @Column(name = "city")
42	    @NotEmpty
43	    private String city;
44	
45	    @Column(name = "telephone")
46	    @NotEmpty
47	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be a valid E.164 number")
48	    private String telephone;
49	
50	    @Column(name = "email")
51	    private String email;
52	
53	    @Column(name = "customer_code")
54	    private String customerCode;
55	
56	    @Column(name = "household_id")
57	    private String householdId;
58	
59	    @Column(name = "namesake_count")
60	    private Integer namesakeCount;
61	
62	    @Column(name = "registration_date")
63	    private java.time.LocalDate registrationDate;
64	
65	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
66	    private Set<Pet> pets;
67	
68	    @PrePersist
69	    private void defaultRegistrationDate() {
70	        if (this.registrationDate == null) {
71	            this.registrationDate = java.time.LocalDate.now();
72	        }
73	    }
74	
75	    public java.time.LocalDate getRegistrationDate() {
76	        return this.registrationDate;
77	    }
78	
79	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
80	        this.registrationDate = registrationDate;
81	    }
82	
83	    public String getCustomerCode() {
84	        return this.customerCode;
85	    }
86	
87	    /**
88	     * Assign this owner's customerCode as '<CITY3>-<LAST3>-<NNNN>', where CITY3 and
89	     * LAST3 are the upper-cased first three letters of the city and last name and
90	     * NNNN is a 4-digit, zero-padded sequence one greater than the number of owners
91	     * already in this owner's city.
92	     */
93	    public void assignCustomerCode(int existingCityCount) {
94	        String city3 = this.city.substring(0, Math.min(3, this.city.length())).toUpperCase(Locale.ROOT);
95	        String last3 = this.lastName.substring(0, Math.min(3, this.lastName.length())).toUpperCase(Locale.ROOT);
96	        this.customerCode = String.format("%s-%s-%04d", city3, last3, existingCityCount + 1);
97	    }
98	
99	    public Integer getNamesakeCount() {
100	        return this.namesakeCount;
101	    }
102	
103	    public void setNamesakeCount(Integer namesakeCount) {
104	        this.namesakeCount = namesakeCount;
105	    }
106	
107	    public String getHouseholdId() {
108	        return this.householdId;
109	    }
110	
111	    public void setHouseholdId(String householdId) {
112	        this.householdId = householdId;
113	    }
114	
115	    public String getEmail() {
116	        return this.email;
117	    }
118	
119	    public void setEmail(String email) {
120	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
121	    }
122	
123	    public String getAddress() {
124	        return this.address;
125	    }
126	
127	    public void setAddress(String address) {
128	        this.address = PostalAddress.normalize(address);
129	    }
130	
131	    public String getCity() {
132	        return this.city;
133	    }
134	
135	    public void setCity(String city) {
136	        this.city = city;
137	    }
138	
139	    public String getTelephone() {
140	        return this.telephone;
141	    }
142	
143	    public void setTelephone(String telephone) {
144	        this.telephone = TelephoneNumber.toE164(telephone);
145	    }
146	
147	    protected Set<Pet> getPetsInternal() {
148	        if (this.pets == null) {
149	            this.pets = new HashSet<>();
150	        }
151	        return this.pets;
152	    }
153	
154	    protected void setPetsInternal(Set<Pet> pets) {
155	        this.pets = pets;
156	    }
157	
158	    public List<Pet> getPets() {
159	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
160	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
161	        return Collections.unmodifiableList(sortedPets);
162	    }
163	
164	    public void setPets(List<Pet> pets) {
165	        this.pets = new HashSet<>(pets);
166	    }
167	
168	    public void addPet(Pet pet) {
169	        getPetsInternal().add(pet);
170	        pet.setOwner(this);
171	    }
172	
173	    /**
